import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Vibe Coding 理念","description":"2025 年提出的 AI 原生构建方式：自然语言描述目标、AI 实现迭代、人负责方向判断与验收——及其与传统编程的对照。","frontmatter":{"title":"Vibe Coding 理念","description":"2025 年提出的 AI 原生构建方式：自然语言描述目标、AI 实现迭代、人负责方向判断与验收——及其与传统编程的对照。","domain":"tech","tags":["tech","methodology","legacy","vibe-coding"],"navOrder":85,"topicId":"methodology-vibe-coding","layer":"appendix","status":"legacy","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/methodology/vibe-coding-philosophy.md","filePath":"zh/tech/appendices/methodology/vibe-coding-philosophy.md","lastUpdated":1791123418000}'),d={name:"zh/tech/appendices/methodology/vibe-coding-philosophy.md"};function r(n,t,s,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="vibe-coding-理念" tabindex="-1">Vibe Coding 理念 <a class="header-anchor" href="#vibe-coding-理念" aria-label="Permalink to &quot;Vibe Coding 理念&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://www.vibevibe.cn/" target="_blank" rel="noreferrer">Vibe Vibe</a> ｜ 原文引用于 Andrej Karpathy (2025)</p></blockquote><h2 id="什么是-vibe-coding" tabindex="-1">什么是 Vibe Coding <a class="header-anchor" href="#什么是-vibe-coding" aria-label="Permalink to &quot;什么是 Vibe Coding&quot;">​</a></h2><blockquote><p>&quot;There&#39;s a new kind of coding I call &#39;vibe coding&#39;, where you fully give in to the vibes, embrace exponentials, and forget that the code even exists.&quot; — <strong>Andrej Karpathy</strong>, 2025</p></blockquote><p>Vibe Coding 是 2025 年提出的代表性 <strong>AI 原生构建方式</strong>，也是 Collins 词典年度词汇。核心特征：</p><ol><li><strong>用自然语言描述目标与需求</strong>，而不是所有步骤亲手完成</li><li><strong>让 AI 参与实现、组织和迭代</strong>，你负责验收、判断和调整</li><li><strong>更快把想法变成真实成果</strong>——做出东西往往比空想和完美规划更能推动学习</li></ol><p>简单说：<strong>你负责方向、判断和审美，AI 帮你把作品做出来。</strong></p><h2 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h2><ul><li><strong>零基础友好</strong>：从想法开始，不需要编程经验</li><li><strong>AI 创造工作流</strong>：用 AI 梳理想法、搭原型、补内容、改交互、推上线——而不只是把 AI 当写代码的工具</li><li><strong>MVP 思维</strong>：最少时间验证想法，避免功能蔓延，先完成再完美</li><li><strong>安全底线意识</strong>：从第一天学会保护用户数据、避免常见漏洞</li><li><strong>渐进式学习</strong>：基础篇完成作品 → 进阶篇完善成产品</li></ul><h2 id="vibe-coding-vs-传统编程" tabindex="-1">Vibe Coding vs 传统编程 <a class="header-anchor" href="#vibe-coding-vs-传统编程" aria-label="Permalink to &quot;Vibe Coding vs 传统编程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统编程</th><th>Vibe Coding</th></tr></thead><tbody><tr><td>输入</td><td>代码指令</td><td>自然语言描述目标</td></tr><tr><td>迭代方式</td><td>手动写代码调试</td><td>AI 生成 + 人工验收调整</td></tr><tr><td>关注点</td><td>实现细节</td><td>方向、判断、审美</td></tr><tr><td>效率</td><td>取决于编码速度</td><td>取决于需求描述和判断能力</td></tr><tr><td>适用场景</td><td>需要精确控制的底层实现</td><td>快速验证想法、MVP 构建</td></tr></tbody></table><h2 id="思维转变" tabindex="-1">思维转变 <a class="header-anchor" href="#思维转变" aria-label="Permalink to &quot;思维转变&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统模式：想法 → 写代码（苦力活）→ 调试 → 产出</span></span>
<span class="line"><span>Vibe Coding：想法 → 描述给 AI → AI 生成 → 验收判断 → 调整 → 产出</span></span></code></pre></div><p>核心转变：<strong>执行者 → 验收者</strong>；写代码 → 说清楚要什么；自己实现 → 让 AI 实现、自己把控方向。</p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><table tabindex="0"><thead><tr><th>人群</th><th>推荐路径</th><th>理由</th></tr></thead><tbody><tr><td>设计师 / 产品经理</td><td>基础篇</td><td>零代码基础做出可运行原型</td></tr><tr><td>文科生 / 跨专业</td><td>基础篇</td><td>从最基础概念循序渐进</td></tr><tr><td>前端开发者</td><td>进阶篇</td><td>扩展后端能力成为全栈</td></tr><tr><td>创业者 / 独立开发者</td><td>两者皆可</td><td>快速搭建 MVP</td></tr></tbody></table><h2 id="边界与主线的关系" tabindex="-1">边界与主线的关系 <a class="header-anchor" href="#边界与主线的关系" aria-label="Permalink to &quot;边界与主线的关系&quot;">​</a></h2><p>Vibe Coding 的定位是<strong>把想法变成真实作品</strong>，不是把人训练成资深工程师——不会因此突然精通算法或框架源码。它的「描述需求 + 验收判断」内核正是主线 <a href="/zh/tech/03-context/prompt.html">提示词工程</a>与<a href="/zh/tech/02-inference-interface/structured-output.html">结构化输出</a>的工程化版本；而生产级系统的安全与验证要求见层 5（<a href="/zh/tech/08-production/testing.html">测试</a>、<a href="/zh/tech/08-production/security.html">安全</a>）——那是 vibe 之外必须补上的部分。</p><p><strong>项目资源</strong>：<a href="https://github.com/datawhalechina/vibe-vibe" target="_blank" rel="noreferrer">datawhalechina/vibe-vibe</a></p>`,19)])])}const v=e(d,[["render",r]]);export{m as __pageData,v as default};
